  'A list of values': 'قدروں کی فہرست',
  'A macro engine is not built, and VBA in a file is preserved untouched rather than run.': 'میکرو انجن موجود نہیں، اس لیے فائل میں موجود VBA چلایا نہیں جاتا بلکہ جوں کا توں محفوظ رکھا جاتا ہے۔',
  'A member of the group above': 'اوپر والے گروپ کا ایک رکن',
  'A merge down a column crosses this row — split the merged cells first.': 'کالم میں نیچے کی طرف ضم کیے گئے سیلز اس قطار سے گزرتے ہیں — پہلے ضم شدہ سیلز تقسیم کریں۔',
  'A merged cell back into its cells': 'ضم شدہ سیل واپس اس کے سیلز میں',
