  'A name cannot be empty.': 'نام خالی نہیں ہو سکتا۔',
  'A name for each column, from its header — the Name Manager lists them': 'ہر کالم کے لیے اس کے ہیڈر سے ایک نام — نام مینیجر ان کی فہرست دکھاتا ہے',
  'A name that says what is on "{sheet}":': 'ایسا نام جو بتائے کہ "{sheet}" پر کیا ہے:',
  'A name turns': 'نام بدل دیتا ہے',
  'A new list needs a name to be saved under.': 'نئی فہرست کو محفوظ کرنے کے لیے ایک نام درکار ہے۔',
