  'A new slide with this layout, after the current one': 'موجودہ سلائیڈ کے بعد اس لے آؤٹ والی ایک نئی سلائیڈ',
  'A note on this cell, shown when the pointer rests on it (Shift+F2)': 'اس سیل پر ایک نوٹ، جو پوائنٹر اس پر ٹھہرنے سے دکھائی دیتا ہے (Shift+F2)',
  'A note on {cell}': '{cell} پر نوٹ',
  'A page break cannot start inside a table cell — move the caret out of the table.': 'صفحے کا وقفہ ٹیبل کے سیل کے اندر سے شروع نہیں ہو سکتا — کرسر کو ٹیبل سے باہر لے جائیں۔',
  'A page break goes above the row and left of the column of the cell: pick one past A1': 'صفحہ وقفہ سیل کی قطار کے اوپر اور اس کے کالم کے بائیں لگتا ہے: A1 سے آگے کوئی سیل منتخب کریں',
  'A page break here, and another after — an empty page': 'یہاں ایک صفحہ وقفہ، اور اس کے بعد ایک اور — ایک خالی صفحہ',
  'A password is required to open this {noun}.': 'اس {noun} کو کھولنے کے لیے پاس ورڈ درکار ہے۔',
  'A path starts with a point.': 'راستہ ایک پوائنٹ سے شروع ہوتا ہے۔',
  'A picture cannot go inside a table cell yet — move the caret out of the table.': 'تصویر ابھی ٹیبل کے سیل کے اندر نہیں جا سکتی — کرسر کو ٹیبل سے باہر لے جائیں۔',
  'A picture, a chart, a table or a group has no points to edit — select a shape': 'تصویر، چارٹ، ٹیبل یا گروپ میں ترمیم کے لیے کوئی پوائنٹس نہیں ہوتے — کوئی شکل منتخب کریں',
  'A pie chart draws only its first series.': 'پائی چارٹ صرف اپنی پہلی سیریز بناتا ہے۔',
