  'A query needs a source': 'کوئری کے لیے ایک ماخذ ضروری ہے',
  'A query reads a .csv, .tsv or .txt file': 'کوئری .csv، .tsv یا .txt فائل پڑھتی ہے',
  'A raised number at the caret, and its words at the end of the document': 'کرسر پر ایک بالائی نمبر، اور اس کے الفاظ دستاویز کے آخر میں',
  'A raised number at the caret, and its words under the body': 'کرسر پر ایک بالائی نمبر، اور اس کے الفاظ مرکزی متن کے نیچے',
  'A raised number at the caret, and these words at the end of the document.': 'کرسر پر ایک بالائی نمبر، اور یہ الفاظ دستاویز کے آخر میں۔',
  'A raised number at the caret, and these words under the body.': 'کرسر پر ایک بالائی نمبر، اور یہ الفاظ مرکزی متن کے نیچے۔',
  'A range needs a title.': 'رینج کا عنوان ہونا ضروری ہے۔',
  'A range on this sheet or another, such as East!$A$1:$C$10 — Add puts it in the list.': 'اس شیٹ یا کسی دوسری شیٹ پر کوئی رینج، جیسے East!$A$1:$C$10 — «شامل کریں» اسے فہرست میں ڈال دیتا ہے۔',
  'A range title is letters, digits, spaces, dots, hyphens and underscores.': 'رینج کا عنوان حروف، ہندسوں، اسپیسز، نقطوں، ہائفنز اور انڈر اسکورز پر مشتمل ہوتا ہے۔',
  'A record for which this holds is left out of the merge.': 'جس ریکارڈ پر یہ شرط پوری ہو، اسے مرج سے باہر رکھا جاتا ہے۔',
  'A rectangle with words in it': 'ایک مستطیل جس میں الفاظ ہوں',
  'A rule files mail as it arrives — a newsletter into its own folder, an invoice starred, a mailing list marked read. You can see exactly what one would do before it does anything.': 'قاعدہ میل آتے ہی اسے ترتیب دیتا ہے — نیوز لیٹر اس کے اپنے فولڈر میں، انوائس پر ستارہ، میلنگ لسٹ پڑھی ہوئی کے طور پر نشان زد۔ کوئی قاعدہ کچھ کرنے سے پہلے آپ ٹھیک ٹھیک دیکھ سکتے ہیں کہ وہ کیا کرے گا۔',
  'A scatter chart here plots up to three series — select a block of an X column and up to three Y columns.': 'یہاں اسکیٹر چارٹ زیادہ سے زیادہ تین سیریز دکھاتا ہے — ایک X کالم اور زیادہ سے زیادہ تین Y کالمز کا بلاک منتخب کریں۔',
  'A scheduled or held message sends when Rutba Office is running — one that falls due while it is closed goes out the next time it opens. A failed send stays here with the error and keeps retrying.': 'شیڈول شدہ یا روکا ہوا پیغام اس وقت بھیجا جاتا ہے جب Rutba Office چل رہا ہو — جس پیغام کا وقت اس کے بند ہونے کے دوران آ جائے، وہ اگلی بار کھلنے پر بھیج دیا جاتا ہے۔ جو پیغام نہ جا سکے وہ خرابی کے ساتھ یہیں رہتا ہے اور دوبارہ کوشش ہوتی رہتی ہے۔',
  'A script cannot merge across part of a merged region': 'اسکرپٹ کسی ضم شدہ علاقے کے صرف ایک حصے کو شامل کر کے ضم نہیں کر سکتا',
  'A script cannot set a cell outside the worksheet (A1 to XFD1048576)': 'اسکرپٹ ورک شیٹ سے باہر کسی سیل کی قدر مقرر نہیں کر سکتا (A1 سے XFD1048576 تک)',
  'A script needs a function called main(workbook)': 'اسکرپٹ میں main(workbook) نام کا فنکشن ہونا ضروری ہے',
  'A sender goes on the Safe or the Blocked list.': 'بھیجنے والے کو محفوظ فہرست یا بلاک شدہ فہرست میں رکھا جاتا ہے۔',
  'A sentence or two is usually right.': 'عموماً ایک دو جملے کافی ہوتے ہیں۔',
  'A series is linear, growth, dates or AutoFill': 'سیریز خطی، افزائش، تاریخیں یا خودکار بھرائی ہوتی ہے',
  'A series starts from a number or a date in the first cell': 'سیریز پہلے سیل میں موجود کسی نمبر یا تاریخ سے شروع ہوتی ہے',
  'A sheet of labels, each after the first starting with «Next Record». Put an Address Block in the first, then Update Labels.': 'لیبلز کی ایک شیٹ، جس میں پہلے کے بعد ہر لیبل «Next Record» سے شروع ہوتا ہے۔ پہلے لیبل میں ایڈریس بلاک رکھیں، پھر «لیبلز اپ ڈیٹ کریں»۔',
  'A sidebar stands beside the story with the words that go with it: a summary, a list of points, a note for the reader.': 'سائیڈ بار مضمون کے ساتھ اس سے متعلق الفاظ لیے رہتا ہے: خلاصہ، نکات کی فہرست، قاری کے لیے کوئی نوٹ۔',
  'A signature line cannot go inside a table cell yet — move the caret out of the table.': 'دستخط لائن ابھی ٹیبل کے سیل کے اندر نہیں جا سکتی — کرسر کو ٹیبل سے باہر لے جائیں۔',
  'A slicer is not grouped with other objects here — take it out of the selection.': 'یہاں سلائسر کو دوسرے آبجیکٹس کے ساتھ گروپ نہیں کیا جاتا — اسے انتخاب سے نکال دیں۔',
  'A slicer keeps at least one item selected — Clear Filter shows them all.': 'سلائسر میں کم از کم ایک آئٹم منتخب رہتا ہے — فلٹر صاف کریں سے سب آئٹمز دکھائی دیتے ہیں۔',
  'A slide with a timing of its own keeps it when timings are used; the rest stay up for the seconds above. Animations are shown finished.': 'جس سلائیڈ کا اپنا وقت مقرر ہو، اوقات استعمال کرنے پر وہی وقت رکھتی ہے؛ باقی سلائیڈز اوپر دیے گئے سیکنڈز تک دکھائی دیتی ہیں۔ اینیمیشنز مکمل حالت میں دکھائی جاتی ہیں۔',
  'A source is already tagged {tag}.': 'ایک ماخذ پر پہلے ہی {tag} کا ٹیگ لگا ہے۔',
  'A style can be linked to one level only.': 'ایک اسٹائل صرف ایک سطح سے منسلک کیا جا سکتا ہے۔',
  'A table needs columns.': 'ٹیبل میں کالمز ہونا ضروری ہیں۔',
  'A table or chart frame has no fill or outline of its own.': 'ٹیبل یا چارٹ فریم کی اپنی کوئی بھرائی یا خاکہ نہیں ہوتا۔',
  'A table row does not fit even on an empty page; the margins leave no body.': 'ٹیبل کی قطار خالی صفحے پر بھی نہیں سماتی؛ حاشیے مرکزی متن کے لیے کوئی جگہ نہیں چھوڑتے۔',
  'A text box cannot be anchored in this paragraph — it is part of a field or a content control.': 'ٹیکسٹ باکس کو اس پیراگراف میں اینکر نہیں کیا جا سکتا — یہ کسی فیلڈ یا مواد کنٹرول کا حصہ ہے۔',
  'A text box goes beside the words, not in a table cell — move the caret out of the table first.': 'ٹیکسٹ باکس الفاظ کے ساتھ آتا ہے، ٹیبل کے سیل میں نہیں — پہلے کرسر کو ٹیبل سے باہر لے جائیں۔',
