  'A word is broken only where the line would otherwise end further than this from the right margin.': 'لفظ صرف وہاں توڑا جاتا ہے جہاں بصورتِ دیگر لائن دائیں حاشیے سے اس فاصلے سے زیادہ دور ختم ہوتی۔',
