  'The picture could not be turned: {error}': 'تصویر گھمائی نہیں جا سکی: {error}',
  'The pivot table goes under the data and its chart beside it; the chart follows the pivot when it is refreshed or filtered.': 'PivotTable ڈیٹا کے نیچے اور اس کا چارٹ اس کے ساتھ رکھا جاتا ہے؛ PivotTable تازہ یا فلٹر ہونے پر چارٹ بھی اس کے ساتھ بدلتا ہے۔',
  'The pivot table goes under the data. Data → Refresh All recalculates it from the source.': 'PivotTable ڈیٹا کے نیچے رکھا جاتا ہے۔ ڈیٹا ← سب تازہ کریں اسے ماخذ سے دوبارہ حساب کرتا ہے۔',
