  'The query\'s name, and its sheet\'s': 'کوئری کا نام، اور اس کی شیٹ کا نام',
  'The recipient list {path} is on a network share, so it is not opened from the letter. Choose it with Select Recipients → Use an Existing List.': 'وصول کنندگان کی فہرست {path} نیٹ ورک شیئر پر ہے، اس لیے اسے خط سے نہیں کھولا جاتا۔ اسے «وصول کنندگان منتخب کریں ← موجودہ فہرست استعمال کریں» سے منتخب کریں۔',
  'The recipient list {path} was not found. Select Recipients to choose it again.': 'وصول کنندگان کی فہرست {path} نہیں ملی۔ اسے دوبارہ منتخب کرنے کے لیے وصول کنندگان منتخب کریں استعمال کریں۔',
