  'The release notes': 'ریلیز نوٹس',
  'The rows copied would land on the list or the criteria — choose a place beside or below them': 'کاپی کی گئی قطاریں فہرست یا معیار کے اوپر آ جائیں گی — ان کے ساتھ یا ان کے نیچے کوئی جگہ منتخب کریں',
  'The script could not run': 'اسکرپٹ نہیں چل سکی',
  'The script ran for more than {count} second and was stopped': { one: 'اسکرپٹ {count} سیکنڈ سے زیادہ چلی، اس لیے اسے روک دیا گیا', other: 'اسکرپٹ {count} سیکنڈ سے زیادہ چلی، اس لیے اسے روک دیا گیا' },
  'The script ran too long': 'اسکرپٹ بہت دیر تک چلتا رہا',
  'The selection already contains merged cells — split them first.': 'انتخاب میں پہلے سے ضم شدہ سیلز موجود ہیں — پہلے انہیں تقسیم کریں۔',
  'The selection holds a formula in its corner and the values to try along its edges. Each cell is filled with what the formula gives for that combination.': 'انتخاب کے کونے میں ایک فارمولا ہے اور اس کے کناروں پر آزمانے کے لیے قدریں۔ ہر سیل میں وہ نتیجہ بھرا جاتا ہے جو فارمولا اس امتزاج کے لیے دیتا ہے۔',
  'The sender supports one-click unsubscribe. A single request is sent to them and nothing else leaves this computer.': 'بھیجنے والا ایک کلک میں رکنیت ختم کرنے کی سہولت دیتا ہے۔ انہیں صرف ایک درخواست بھیجی جاتی ہے، اور اس کے سوا کچھ بھی اس کمپیوٹر سے باہر نہیں جاتا۔',
  'The server answered {status} where a list was asked for.': 'فہرست مانگی گئی تھی، لیکن سرور نے جواب میں {status} دیا۔',
  'The server did not accept the user name and password.': 'سرور نے صارف نام اور پاس ورڈ قبول نہیں کیا۔',
  'The server refused to keep {href}: {status}': 'سرور نے {href} کو محفوظ رکھنے سے انکار کر دیا: {status}',
