  'The shapes the engine can draw': 'وہ اشکال جو انجن بنا سکتا ہے',
  'The sheet is protected — unprotect it to change the ranges': 'شیٹ محفوظ ہے — رینجز تبدیل کرنے کے لیے اس کا تحفظ ختم کریں',
  'The sheet is protected: the ranges stay as they are until it is unprotected.': 'شیٹ محفوظ ہے: جب تک اس کا تحفظ ختم نہ ہو، رینجز جوں کی توں رہیں گی۔',
  'The sheet on one page': 'پوری شیٹ ایک صفحے پر',
