  'The suite has English dictionaries only, so Spelling reads past words in {language} rather than marking them wrong; Office proofs them in {language}.': 'اس سوٹ میں صرف انگریزی لغات ہیں، اس لیے ہجے {language} کے الفاظ کو غلط نشان زد کرنے کے بجائے چھوڑ دیتا ہے؛ Office ان کی جانچ {language} میں کرتا ہے۔',
