  'The windows you open from now on are in the language chosen. Restart Rutba Office to see every window in it.': 'اب سے آپ جو ونڈوز کھولیں گے وہ منتخب کردہ زبان میں ہوں گی۔ ہر ونڈو اس زبان میں دیکھنے کے لیے Rutba Office دوبارہ شروع کریں۔',
  'The windows you open from now on write numbers in the digits chosen.': 'اب سے کھولی جانے والی ونڈوز نمبر منتخب ہندسوں میں لکھیں گی۔',
  'The words along the bottom': 'نیچے کی طرف کے الفاظ',
