  'The workbook\'s structure is protected — Review → Unprotect Workbook': 'ورک بک کا ڈھانچہ محفوظ ہے — جائزہ ← ورک بک کا تحفظ ختم کریں',
  'The workbook’s structure is locked to prevent unwanted changes, such as moving, deleting or adding sheets.': 'ورک بک کا ڈھانچہ مقفل ہے تاکہ ناپسندیدہ تبدیلیاں نہ ہوں، جیسے شیٹس منتقل کرنا، حذف کرنا یا شامل کرنا۔',
  'The workbook’s structure is protected with a password. Type it to take the protection off.': 'ورک بک کا ڈھانچہ پاس ورڈ سے محفوظ ہے۔ تحفظ ہٹانے کے لیے پاس ورڈ ٹائپ کریں۔',
