  'Themes — the suite\'s themes, the same as Presentation\'s; this workbook wears {theme}': 'تھیمز — سوٹ کی تھیمز، وہی جو پریزنٹیشنز میں ہیں؛ اس ورک بک پر {theme} لاگو ہے',
