  'There is no sheet of labels in this document. Start Mail Merge → Labels makes one.': 'اس دستاویز میں لیبلز کی کوئی شیٹ نہیں۔ «میل مرج شروع کریں ← لیبلز» سے ایک شیٹ بن جاتی ہے۔',
