  'There is nothing on the clipboard to paste.': 'کلپ بورڈ پر پیسٹ کرنے کے لیے کچھ نہیں ہے۔',
  'Thesaurus': 'لغتِ مترادفات',
  'Thesaurus (Shift+F7) — words of like meaning for the word at the caret, one of them put in its place': 'لغتِ مترادفات (Shift+F7) — کرسر والے لفظ کے ہم معنی الفاظ، جن میں سے کوئی ایک اس کی جگہ رکھا جا سکتا ہے',
  'Thesaurus (Shift+F7) — words of like meaning for the word in the active cell': 'لغتِ مترادفات (Shift+F7) — فعال سیل میں موجود لفظ کے ہم معنی الفاظ',
  'Thesaurus (Shift+F7) — words of like meaning for the word where the caret was in a shape\'s text': 'لغتِ مترادفات (Shift+F7) — کسی شکل کے متن میں جہاں کرسر تھا، وہاں کے لفظ کے ہم معنی الفاظ',
  'These are imported archives — there is nothing to fetch.': 'یہ درآمد شدہ آرکائیوز ہیں — لانے کے لیے کچھ نہیں ہے۔',
  'These are set with xdg-mime, which this can do directly.': 'یہ xdg-mime سے سیٹ ہوتے ہیں، جو یہ ایپ براہِ راست کر سکتی ہے۔',
  'These cells are part of a vertical merge — widening one row of it would tear the range.': 'یہ سیلز ایک عمودی انضمام کا حصہ ہیں — اس کی ایک قطار چوڑی کرنے سے رینج ٹوٹ جائے گی۔',
  'These settings came from {source} on this computer; they are checked when the address is complete.': 'یہ ترتیبات اس کمپیوٹر پر {source} سے آئی ہیں؛ پتہ مکمل ہونے پر ان کی جانچ کی جاتی ہے۔',
  'They are saved into the presentation, and travel with it.': 'یہ پریزنٹیشن میں محفوظ ہوتے ہیں، اور اس کے ساتھ ہی جاتے ہیں۔',
  'Thick': 'موٹا',
